import { FormsModule, ReactiveFormsModule } from "@angular/forms";
import {LabelValue} from "../../interfaces";

@Component({
  selector: "stc-select-button",
  standalone: true,
  imports: [ReactiveFormsModule, SelectButtonModule, FormsModule],
  templateUrl: "./select-button.component.html",
  styleUrl: "./select-button.component.scss"
})
export class SelectButtonComponent extends BaseInputComponent {
  @Output() onChange: EventEmitter<any> = new EventEmitter<string>();
  @Input() options: LabelValue<any>[];
  @Input() title: string;

  changeValue(e: SelectButtonChangeEvent) {
    this.onChange.emit(e.value);
  }
}

import { NgClass, NgTemplateOutlet } from '@angular/common';
import {
  Component,
  EventEmitter,
  Input,
  Output,
  TemplateRef,
  ViewEncapsulation,
} from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { PrimeTemplate } from 'primeng/api';
import { CheckboxModule } from 'primeng/checkbox';
import { FloatLabelModule } from 'primeng/floatlabel';
import { MultiSelectModule } from 'primeng/multiselect';
import { Select, SelectChangeEvent } from 'primeng/select';
import { ValidationErrorsPipe } from '../../@utils/validations';
import { BaseInputComponent } from '../base-input.component';

@Component({
  selector: 'stc-select',
  standalone: true,
  imports: [
    FormsModule,
    Select,
    ReactiveFormsModule,
    NgClass,
    NgTemplateOutlet,
    PrimeTemplate,
    ValidationErrorsPipe,
    MultiSelectModule,
    FloatLabelModule,
    TranslatePipe,
    CheckboxModule,
  ],
  templateUrl: './select.component.html',
  styleUrl: './select.component.scss',
  encapsulation: ViewEncapsulation.None,
})
export class SelectComponent extends BaseInputComponent {
  @Input() selectedItemTemplate: TemplateRef<unknown> | null = null;
  @Input() optionTemplate: TemplateRef<unknown> | null = null;
  @Input() options: unknown[] = [];
  @Input() optionLabel!: string;
  @Input() optionValue!: string;
  @Input() emptyMessage!: string;
  @Input() checkmark = true;
  @Input() showClear = false;
  @Input() editable = false;
  @Input() filter = false;
  @Input() multiple = false;
  @Input() filterBy!: string;
  @Input() selectAllLabel: string;
  @Input() dataKey!: string;
  @Input() size: 'small' | 'large' = 'small';
  @Input() appendTo = '';

  @Input() selectedItemsLabel!: string;
  @Input() basicInput!: boolean;
  @Input() variant: 'in' | 'over' | 'on' = 'over';
  @Output() change = new EventEmitter();
  @Output() clicked = new EventEmitter();

  @Input() defaultColor = '#DFE0E6';
  allSelectd = false;

  constructor() {
    super();
  }

  toggleAll(event: any) {
    if (!event.checked) {
      this.control.setValue([]);
      return;
    }
    const values = this.optionValue
      ? this.options.map((o) => (o as Record<string, unknown>)[this.optionValue as string])
      : this.options;
    this.control.setValue([...values]);
  }

  onMultiSelectClear() {
    this.allSelectd = false;
  }

  onChange(e: SelectChangeEvent) {
    this.change.emit(e);
  }

  onClick(event: Event) {
    this.clicked.emit(event);
  }
}

import { NgClass, NgTemplateOutlet } from "@angular/common";
import { Component, EventEmitter, Input, Output, TemplateRef, ViewEncapsulation } from "@angular/core";
import { PrimeTemplate } from "primeng/api";
import { Drawer } from "primeng/drawer";
import { TooltipModule } from "primeng/tooltip";

@Component({
  selector: "app-side-bar",
  standalone: true,
  imports: [PrimeTemplate, Drawer, NgClass, NgTemplateOutlet, TooltipModule],
  templateUrl: "./side-bar.component.html",
  styleUrl: "./side-bar.component.scss",
  encapsulation: ViewEncapsulation.None
})
export class SideBarComponent {
  @Input() show = false;
  @Input() title: string;
  @Input() closable = true;
  @Input() dismissible = false;
  @Input() closeOnEscape = false;
  @Input() sidebarSize: "sm" | "md" | "lg" | "xl" = "sm";
  @Input() styleClass = "";
  @Output() hide = new EventEmitter<boolean>();
  @Output() onShow = new EventEmitter<boolean>();
  @Input() contentTemplate!: TemplateRef<unknown>;
  @Input() footerTemplate!: TemplateRef<unknown>;
  @Input() position  = 'left';

  hideSidebar() {
    this.show = false;
    this.hide.emit(false);
  }
}

import {NgClass, NgComponentOutlet} from "@angular/common";
import {Component, inject, Injector, OnDestroy, OnInit} from '@angular/core';
import {PrimeTemplate} from "primeng/api";
import {Drawer} from "primeng/drawer";
import { Location } from '@angular/common';
import {TranslatePipe} from "@ngx-translate/core";
import { DataInjectorPipe } from "./data-injector.pipe";
import { AppButtonComponent } from "../app-button";
import { DynamicSidebarService } from "./dynamic-sidebar.service";
import { createCustomInjector, SIDEBAR_DATA } from "./side-bar-utils";
@Component({
  selector: "app-side-bar-dynamic",
  templateUrl: "./side-bar-dynamic.component.html",
  styleUrls: ["./side-bar-dynamic.component.scss"],
  standalone: true,
  imports: [Drawer, NgClass, NgComponentOutlet, PrimeTemplate, DataInjectorPipe, AppButtonComponent, TranslatePipe]
})
export class SideBarDynamicComponent implements OnInit, OnDestroy {
  dynamicSidebarService = inject(DynamicSidebarService);
  parentInjector = inject(Injector);
  location = inject(Location);
  private popStateListener: any;
  sidebarConfig = this.dynamicSidebarService.sidebarConfig;
  ngOnInit() {
    //To close a sidebar when the browser back button is pressed
    this.popStateListener = this.location.subscribe(() => {
      if (this.dynamicSidebarService.sidebarConfig.visible) {
        this.dynamicSidebarService.close();
      }
    });
  }

  ngOnDestroy() {
    // reset Sidebar token
    createCustomInjector(this.parentInjector, SIDEBAR_DATA, null);
  }
}

import { Component, EventEmitter, Input, Output } from "@angular/core";
import { CommonModule } from "@angular/common";
